#include HEADER
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
volatile std::uint64_t observation = 0;
template<class UInt>std::uint64_t measure(int n,int k,int reps,int mix){
 std::uint64_t sum=0;
 for(int i=0;i<reps;++i){
  if(mix)for_each_combination<UInt>(n,k,[&](UInt m){sum ^= static_cast<std::uint64_t>(m)+UINT64_C(0x9e3779b97f4a7c15)+(sum<<6)+(sum>>2);});
  else for_each_combination<UInt>(n,k,[&](UInt m){sum+=m;});
  observation=sum;
 }
 return sum;
}
int main(int argc,char**argv){if(argc!=6)return 1;int width=std::atoi(argv[1]),n=std::atoi(argv[2]),k=std::atoi(argv[3]),reps=std::atoi(argv[4]),mix=std::atoi(argv[5]);auto t=std::chrono::steady_clock::now();std::uint64_t sum=0;
 if(width==8)sum=measure<std::uint8_t>(n,k,reps,mix);
 if(width==32)sum=measure<std::uint32_t>(n,k,reps,mix);
 if(width==64)sum=measure<std::uint64_t>(n,k,reps,mix);
 std::cout<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count()<<' '<<sum<<'\n';
}

